/**
 * Prints the two URLs the venue poster QR codes must encode.
 *
 * The codes are generated by hand in whatever QR tool is at hand, and a typo in
 * the host, the path, a parameter name or the token only shows up when someone
 * scans the printed poster at the door. This builds both URLs from the same
 * `APP_URL` and `CHECKIN_QR_TOKEN` the server reads, and checks each one with
 * the server's own parsing before printing it.
 *
 *   docker compose exec app node scripts/qr/urls.ts
 *
 * Run it inside the production container so it reads the values that stack
 * actually serves with. It reads those two variables alone, through the same
 * `required` the server uses, rather than loading `src/config/env.ts`, whose
 * boot checks on unrelated secrets would refuse a partial or placeholder
 * `.env`. Nothing is written and no database is touched.
 */
import 'dotenv/config';

import { required } from '../../src/config/read-env.ts';
import { toAudienceRole } from '../../src/constants/audience.ts';
import { QR_TOKEN_PATTERN } from '../../src/constants/qr-token.ts';
import { qrService } from '../../src/modules/qr/qr.service.ts';

import type { AttendeeRole } from '../../src/types/attendee.ts';

/** Poster URL for each audience. */
export interface QrUrls {
  participant: string;
  volunteer: string;
}

/**
 * Confirms the server reads back the token and audience a URL was built with.
 *
 * @param url - URL about to be printed.
 * @param qrToken - Token it must carry.
 * @param audience - Audience it must name, or `undefined` for none.
 * @throws {Error} If either reads back differently.
 */
const assertRoundTrip = (
  url: URL,
  qrToken: string,
  audience: AttendeeRole | undefined,
): void => {
  if (qrService.extractToken(url.href) !== qrToken) {
    throw new Error(`${url.href} does not carry the QR token`);
  }

  if (
    toAudienceRole(url.searchParams.get('audience') ?? undefined) !== audience
  ) {
    throw new Error(
      `${url.href} does not name audience ${audience ?? '(none)'}`,
    );
  }
};

/**
 * Builds the participant and volunteer poster URLs.
 *
 * @param options.appUrl - Public origin, as `APP_URL` holds it.
 * @param options.qrToken - Poster token, as `CHECKIN_QR_TOKEN` holds it.
 * @returns Both URLs, verified against the server's parsing.
 * @throws {Error} If either input would produce a code the door rejects.
 */
export const buildQrUrls = ({
  appUrl,
  qrToken,
}: {
  appUrl: string;
  qrToken: string;
}): QrUrls => {
  if (!QR_TOKEN_PATTERN.test(qrToken)) {
    throw new Error(
      `CHECKIN_QR_TOKEN must match ${QR_TOKEN_PATTERN.source}; every scan would be rejected`,
    );
  }

  let base: URL;

  try {
    base = new URL(appUrl);
  } catch {
    throw new Error(`APP_URL is not an absolute URL: "${appUrl}"`);
  }

  if (base.protocol !== 'https:' && base.protocol !== 'http:') {
    throw new Error(`APP_URL must be http(s): "${appUrl}"`);
  }

  // `new URL('/checkin', base)` would silently drop any of these.
  if (base.pathname !== '/' || base.search || base.hash) {
    throw new Error(`APP_URL must be a bare origin: "${appUrl}"`);
  }

  const participant = new URL('/checkin', base);
  participant.searchParams.set('k', qrToken);
  assertRoundTrip(participant, qrToken, undefined);

  const volunteer = new URL('/checkin', base);
  volunteer.searchParams.set('audience', 'volunteer');
  volunteer.searchParams.set('k', qrToken);
  assertRoundTrip(volunteer, qrToken, 'volunteer');

  return { participant: participant.href, volunteer: volunteer.href };
};

if (import.meta.main) {
  try {
    const urls = buildQrUrls({
      appUrl: required('APP_URL'),
      qrToken: required('CHECKIN_QR_TOKEN'),
    });

    console.log(`Participants: ${urls.participant}`);
    console.log(`Volunteers:   ${urls.volunteer}`);
  } catch (err) {
    console.error((err as Error).message);
    process.exitCode = 1;
  }
}
